/**
 * OpenNext fetch handler plus ArcadeX Durable Object exports.
 * `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
 *
 * Public catalog/document hits are answered from the Cache API before
 * OpenNext starts. That is the expensive part of Workers CPU time.
 */

// @ts-expect-error generated at OpenNext build time
import nextWorker from "../.open-next/worker.js";
import { maybeServeHotCache, maybeStoreHotCache } from "./hot-cache";

type WorkerEnv = {
  CF_VERSION_METADATA?: { id?: string };
};

type WaitCtx = {
  waitUntil(promise: Promise<unknown>): void;
};

type NextWorker = {
  fetch: (
    request: Request,
    env: WorkerEnv,
    ctx: WaitCtx
  ) => Promise<Response> | Response;
};

function resolveNextFetch(mod: unknown): NextWorker["fetch"] {
  if (typeof mod === "function") {
    return mod as NextWorker["fetch"];
  }
  const fetchFn = (mod as NextWorker | undefined)?.fetch;
  if (typeof fetchFn === "function") {
    return fetchFn.bind(mod) as NextWorker["fetch"];
  }
  throw new Error("OpenNext worker is missing a fetch handler.");
}

const nextFetch = resolveNextFetch(nextWorker);

export default {
  async fetch(request: Request, env: WorkerEnv, ctx: WaitCtx): Promise<Response> {
    const hit = await maybeServeHotCache(request, env);
    if (hit) return hit;

    const response = await nextFetch(request, env, ctx);
    maybeStoreHotCache(request, response, env, ctx);
    return response;
  },
};

export { ShuffleBudgetDO } from "./shuffle-budget-do";
